20	public class PasswordEntryDialog extends AppCompatDialog
21	    implements View.OnClickListener, TextWatcher {
22	
23	    public enum Mode { ENTER, UPDATE }
24	
25	    public interface PasswordEnteredCallback {
26	        void onPasswordEntered(String newPassword);
27	    }
