36	    public PasswordEntryDialog(Context context, Mode newMode, boolean blockAccessibility, boolean blockAutofill, PasswordEnteredCallback newCallback) {
37	        super(context, Tools.getThemeResource(context, R.attr.dialogTheme));
38	
39	        setTitle(R.string.dialog_title_enter_password);
40	        setContentView(R.layout.dialog_password_entry);
41	
42	        TextInputLayout passwordLayout = findViewById(R.id.passwordInputLayout);
43	        passwordInput = findViewById(R.id.passwordInput);
44	        passwordConfirm = findViewById(R.id.passwordConfirm);
45	
46	        if (blockAccessibility) {
47	            passwordLayout.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);
48	            passwordConfirm.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
49	        }
50	
51	        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O && blockAutofill) {
52	            passwordLayout.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);
53	            passwordConfirm.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);
54	        }
55	
56	        okButton = findViewById(R.id.buttonOk);
57	        Button cancelButton = findViewById(R.id.buttonCancel);
58	
59	        okButton.setOnClickListener(this);
60	        cancelButton.setOnClickListener(this);
61	
62	        this.callback = newCallback;
63	
64	        this.dialogMode = newMode;
65	
66	        if (this.dialogMode == Mode.UPDATE) {
67	            passwordConfirm.setVisibility(View.VISIBLE);
68	            passwordInput.addTextChangedListener(this);
69	            passwordConfirm.addTextChangedListener(this);
70	        } else if (this.dialogMode == Mode.ENTER) {
71	            passwordConfirm.setVisibility(View.GONE);
72	        }
73	    }
