75	    // TextWatcher
76	    public void onTextChanged(CharSequence s, int start, int before, int count) {
77	        if (TextUtils.equals(passwordInput.getEditableText(), passwordConfirm.getEditableText()))
78	            okButton.setEnabled(true);
79	        else
80	            okButton.setEnabled(false);
