87	    public void onClick(View view)  {
88	        if (view.getId() == R.id.buttonOk) {
89	            if (callback != null)
90	                callback.onPasswordEntered(passwordInput.getText().toString());
91	        }
92	
93	        dismiss();
94	    }
95	}
