171	    private void saveValues() {
172	        byte[] newKey = null;
173	
174	        if (settings.getEncryption() == EncryptionType.PASSWORD) {
175	            if (value == AuthMethod.NONE || value == AuthMethod.DEVICE) {
176	                UIHelper.showGenericDialog(getContext(), R.string.settings_dialog_title_error, R.string.settings_dialog_msg_auth_invalid_with_encryption);
177	                return;
178	            }
179	        }
180	
181	        if (value == AuthMethod.DEVICE) {
182	            KeyguardManager km = (KeyguardManager) getContext().getSystemService(KEYGUARD_SERVICE);
183	
184	            if (! km.isKeyguardSecure()) {
185	                Toast.makeText(getContext(), R.string.settings_toast_auth_device_not_secure, Toast.LENGTH_LONG).show();
186	                return;
187	            }
188	        }
189	
190	        if (value == AuthMethod.PASSWORD || value == AuthMethod.PIN) {
191	            String password = passwordInput.getText().toString();
192	            if (!password.isEmpty()) {
193	                newKey = settings.setAuthCredentials(password);
194	            } else {
195	                return;
196	            }
197	        }
198	
199	        if (settings.getEncryption() == EncryptionType.PASSWORD) {
200	            if (newKey == null || encryptionChangeCallback == null)
201	                return;
202	
203	            if (! encryptionChangeCallback.testEncryptionChange(newKey))
204	                return;
205	        }
206	
207	        persistString(value.toString().toLowerCase());
208	        setSummary(entries.get(entryValues.indexOf(value)));
209	    }
